INSERT INTO `short_work` (`work_id`, `user_id`, `work_title`, `one_line_pitch`, `genre`, `work_status`, `episode_count`, `episode_duration_sec`, `visual_style`, `aspect_ratio`, `cover_asset_id`, `cost_budget_cent`, `cost_spent_cent`, `skip_level_check_flag`, `quality_threshold_score`, `outline_json`, `compose_setting_json`, `archived_flag`, `deleted_flag`) VALUES ('w-dm-001', 'u-demo-0001', '退婚三年后她成了首富', '被退婚的落魄千金三年后带着资本回归，收购前未婚夫的公司', 'REVENGE', 'PRODUCING', 4, 90, 'MODERN_URBAN', 'VERTICAL_9_16', 'as-dm-001-cover', 300000, 12850, 0, 75, '[{"episode_no":1,"episode_title":"开场","episode_synopsis":"被退婚的落魄千金三年后带着资本回归，收购前未婚夫的公司。第 1 集当众爆发冲突。","ending_hook":"她抬眼：这事没完。"},{"episode_no":2,"episode_title":"第2集","episode_synopsis":"第 2 集推进：被退婚的落魄千金三年后带着资本回归，收购前未婚夫的公司 的下一手。","ending_hook":"反派冷笑：你以为这就赢了？"},{"episode_no":3,"episode_title":"第3集","episode_synopsis":"第 3 集推进：被退婚的落魄千金三年后带着资本回归，收购前未婚夫的公司 的下一手。","ending_hook":"反派冷笑：你以为这就赢了？"},{"episode_no":4,"episode_title":"终局","episode_synopsis":"退婚三年后她成了首富迎来收束，旧账当场清算。","ending_hook":"镜头定格在她转身离开的背影。"}]', '{"compose_mode":"FULL","fps":30,"resolution":"1080x1920"}', 0, 0);
