INSERT INTO `short_episode` (`episode_id`, `work_id`, `user_id`, `episode_no`, `episode_title`, `episode_synopsis`, `ending_hook`, `script_status`, `storyboard_status`, `dubbing_status`, `compose_status`, `review_status`, `film_asset_id`, `film_duration_sec`, `deleted_flag`) VALUES ('ep-dm-005-01', 'w-dm-005', 'u-demo-0001', 1, '第1集·旧案重启', '江砚复核一桩三年前定性为自杀的旧案，发现死者颈部有第二处创口，而当年鉴定书上签着她导师秦鹤年的名字。', '她翻到最后一页，签名栏的笔迹她认得——那是导师给她写推荐信的那支笔。', 'READY', 'READY', 'READY', 'READY', 'PENDING', 'as-dm-005-film01', 88, 0);
INSERT INTO `short_script` (`script_id`, `episode_id`, `work_id`, `user_id`, `script_version`, `script_status`, `scene_json`, `estimated_total_sec`, `rhythm_json`, `total_score`, `force_ready_flag`) VALUES ('sp-dm-005-01', 'ep-dm-005-01', 'w-dm-005', 'u-demo-0001', 2, 'READY', '[{"scene_no":1,"scene_location":"解剖室","scene_summary":"无影灯下，江砚俯身看向遗体颈部","line_list":[{"line_no":1,"character_name":"江砚","line_text":"三年前这具遗体，颈动脉窦上有两处创口。","emotion":"COLD","estimated_sec":8},{"line_no":2,"character_name":"周敏","line_text":"可鉴定书上只写了一处。","emotion":"SHOCK","estimated_sec":6},{"line_no":3,"character_name":"江砚","line_text":"把编号 07 的原始记录调出来，要纸质的。","emotion":"CALM","estimated_sec":7}]},{"scene_no":2,"scene_location":"卷宗档案室","scene_summary":"周敏抬头看向贴着封条的档案架","line_list":[{"line_no":1,"character_name":"周敏","line_text":"库房说纸质件三年前就封存了。","emotion":"TENSE","estimated_sec":6},{"line_no":2,"character_name":"江砚","line_text":"封存不是销毁。跟我来。","emotion":"COLD","estimated_sec":6},{"line_no":3,"character_name":"江砚","line_text":"灰是新的——有人比我们先到。","emotion":"TENSE","estimated_sec":9},{"line_no":4,"character_name":"周敏","line_text":"老师……签字栏是秦教授。","emotion":"SHOCK","estimated_sec":7},{"line_no":5,"character_name":"陆行舟","line_text":"江法医，这案子三年前就结了。","emotion":"COLD","estimated_sec":7},{"line_no":6,"character_name":"江砚","line_text":"结了的案子，不该有两份鉴定书。","emotion":"COLD","estimated_sec":8},{"line_no":7,"character_name":"陆行舟","line_text":"你要是错了，赔上的是你自己的职业生涯。","emotion":"TENSE","estimated_sec":9}]},{"scene_no":3,"scene_location":"解剖室","scene_summary":"江砚独自留在解剖室，只开了一盏灯","line_list":[{"line_no":1,"character_name":"江砚","line_text":"他教我的第一课是，尸体不会说谎。","emotion":"COLD","estimated_sec":8},{"line_no":2,"character_name":"江砚","line_text":"那说谎的，就是活人。","emotion":"COLD","estimated_sec":7}]}]', 88, '{"hook_score":86,"beat_score":80,"dialogue_score":88,"ending_score":90,"total_score":86,"estimated_total_sec":88,"issue_list":[]}', 86, 0);
