SET `config_json` = JSON_SET(COALESCE(NULLIF(`config_json`, ''), '{}'), '$.public_alias', 'bgssai-tts', '$.public_name', 'BGSSAI TTS')
WHERE `model_id` = 'm-tokenhub-voice-bgssai-tts'
