UPDATE `ai_model_config` SET `provider_code` = 'TENCENT_TOKENHUB', `model_name` = 'BGSSAI Video', `enabled_flag` = 1, `deleted_flag` = 0, `timeout_sec` = GREATEST(COALESCE(`timeout_sec`, 0), 900), `default_flag` = 1, `config_json` = '{"hub":"cn","secret_ref":"ai.tokenhub_cn.api_key","poll_interval_ms":3000,"public_alias":"bgssai-video","public_name":"BGSSAI Video"}' WHERE `ability_type` = 'VIDEO' AND `provider_code` = 'TENCENT_TOKENHUB' AND `model_code` = 'bgssai-video' AND `deleted_flag` = 0;

